import json
from html import escape, unescape
from html.parser import HTMLParser
from pathlib import Path

sources = json.loads(Path('source.json').read_text())
refs = json.loads(Path('reference-targets.json').read_text())
by_number = {s['number']: s for s in sources}

def paragraphs(*texts):
    return ''.join('<p>' + escape(t, quote=False) + '</p>' for t in texts)

class Text(HTMLParser):
    def __init__(self):
        super().__init__(); self.out = []
    def handle_data(self, data):
        self.out.append(data)
    def handle_starttag(self, tag, attrs):
        if tag in ['p', 'br', 'div', 'li', 'tr', 'td', 'th']: self.out.append(' ')
    def handle_endtag(self, tag):
        if tag in ['p', 'div', 'li', 'tr', 'td', 'th']: self.out.append(' ')

def plain(xml):
    p = Text(); p.feed(xml or ''); return ' '.join(''.join(p.out).split())

answer = []
for s in sources:
    a = {k: s[k] for k in ['code_id', 'source_id', 'source_sha256', 'number']}
    a.update(proposed_xml=s['previous_draft']['proposed_xml'], status='rewrite_draft')
    answer.append(a)
rows = {a['number']: a for a in answer}

def reduce(number, removed):
    rows[number].update(change_type='normative_reduction', reform_policy_id='editorial_direction_2026_10_19', removed_provisions=removed)

def impact(number, classification, assessment, limits, burdens, effects=None):
    rows[number]['substantive_impact'] = dict(version=1, classification=classification, assessment=assessment, scope_limitations=limits, new_burdens_review=burdens, effects=effects or [])

def effect(number, kind, measure, description, before, after, unit, population, transition, burdens, source_quote, proposed_quote):
    assert source_quote in plain(by_number[number]['source_xml']), (number, 'source quote', source_quote)
    assert proposed_quote in plain(rows[number]['proposed_xml']), (number, 'proposed quote', proposed_quote)
    return dict(kind=kind, measure_id=measure, description=description, before=before, after=after, unit=unit, affected_population=population, conditions_and_transition=transition, replacement_or_new_burdens=burdens, source_quote=source_quote, proposed_quote=proposed_quote)

